@import "tailwindcss";

@theme {
  --font-sans: "Inter Variable", Inter, ui-sans-serif, system-ui, sans-serif;
  --color-ink: #0f172a;
  --color-ink-2: #475569;
  --color-ink-3: #64748b;
  --color-line: #e2e8f0;
  --color-panel: #f8fafc;
