function Via({ a }: { a: ActivityItem }) {
  const v = viaOf(a)
  if (!v) return null
  const chip = 'inline-flex max-w-full items-center gap-1 rounded bg-ok/10 px-1.5 py-0.5 text-xs font-semibold text-ok'
