import { CheckCircle2, Mic, Sparkles, Workflow, X } from 'lucide-react'
import { DecisionCard } from '@/components/DecisionCard'
import { Button } from '@/components/ui/button'
import { DONE_WORD, ago, fmtDay, fmtTime, sentence, tidy, viaOf, type ActivityItem, type Card, type State } from '@/lib/api'
import type { MapSelection } from '@/components/SupplyMap'

interface Props {
  state: State
  nowMs: number
  selection: MapSelection
  onClear: () => void
  fresh: Set<string>
  /** A card the person just decided: offer to handle the next one like it on its own. */
  decided: Card | null
  onAutomate: (card: Card) => void
  onSkipAutomate: () => void
  onChanged: () => void
  onHover: (routes: string[]) => void
  onDrawer: (card: Card, tab: 'evidence' | 'trail') => void
}

export const HEADING = 'text-xs font-semibold uppercase tracking-wide text-ink-3'

export function Rail(p: Props) {
  const { state, selection } = p
  const match = (c: Card) =>
    selection.routeId ? c.routes.includes(selection.routeId) : selection.nodeId ? c.supplier_id === selection.nodeId : true
  const mine = state.cards.filter((c) => c.status === 'open' && !c.routed_to_other && match(c))
  const withOther = state.cards.filter((c) => (c.routed_to_other && c.status === 'open') || c.status === 'escalated')
  const filterName = selection.routeId
    ? `route ${selection.routeId}`
    : selection.nodeId
      ? state.map.nodes.find((n) => n.id === selection.nodeId)?.name
      : null

  const card = (c: Card) => (
    <DecisionCard
      key={c.id}
      card={c}
      cards={state.cards}
      nowMs={p.nowMs}
      isNew={p.fresh.has(c.id)}
      onChanged={p.onChanged}
      onHover={p.onHover}
      onDrawer={p.onDrawer}
    />
  )

  return (
    <div className="space-y-4">
      {p.decided && (
        <AutomateOffer card={p.decided} onYes={() => p.onAutomate(p.decided!)} onNo={p.onSkipAutomate} />
      )}

      {filterName && (
        <button
          onClick={p.onClear}
          className="inline-flex cursor-pointer items-center gap-2 rounded-full bg-ink px-3.5 py-1.5 text-sm font-semibold text-white"
        >
          Showing {filterName} <X size={14} />
        </button>
      )}

      {mine.length > 0 ? (
        <>
          <h1 className={HEADING}>Needs you · {mine.length}</h1>
          {mine.map(card)}
        </>
      ) : (
        <Calm state={state} nowMs={p.nowMs} filtered={!!filterName} waiting={withOther.length} />
      )}

      {withOther.length > 0 && (
        <>
          <h2 className={`pt-2 ${HEADING}`}>With others · {withOther.length}</h2>
          {withOther.map(card)}
        </>
      )}

      <Activity items={state.activity} />
    </div>
  )
}

/** The one place that offers automation: after a decision, by button or by voice. */
export function AutomateOffer({ card, onYes, onNo }: { card: Card; onYes: () => void; onNo: () => void }) {
  return (
    <section className="slide-in rounded-xl border-2 border-ok/40 bg-ok/5 p-4" aria-live="polite">
      <div className="flex items-start gap-1.5 text-sm font-semibold text-ok">
        <CheckCircle2 size={16} className="mt-0.5 shrink-0" />
        <span className="min-w-0">{DONE_WORD[card.status] ?? 'Done'}: {tidy(card.headline)}</span>
      </div>
      <div className="mt-1.5 text-[17px] font-bold leading-snug">Handle the next one like this on its own?</div>
      <p className="mt-1 text-[15px] text-ink-2">
        You'll see what it would do before it starts. Anything that costs money or changes the plan still comes to you.
      </p>
      <div className="mt-3 flex gap-2">
        <Button size="sm" onClick={onYes}><Sparkles size={16} /> Show me how</Button>
        <Button size="sm" variant="ghost" onClick={onNo}>Not now</Button>
      </div>
    </section>
  )
}

function Calm({ state, nowMs, filtered, waiting }: { state: State; nowMs: number; filtered: boolean; waiting: number }) {
  const suppliers = new Set(state.shipments.map((s) => s.supplier_id)).size
  return (
    <section className="rounded-2xl border border-line p-5 sm:p-6">
      <CheckCircle2 size={32} className="text-ok" />
      <h1 className="mt-3 text-[22px] font-extrabold leading-tight sm:text-[24px]">
        {filtered ? 'Nothing open here.' : 'Nothing needs you right now.'}
      </h1>
      <p className="mt-2 text-[15px] text-ink-2">
        {waiting > 0 && `${waiting} ${waiting === 1 ? 'decision is' : 'decisions are'} with others. `}
        Agents are watching {state.shipments.length} shipments from {suppliers} suppliers and every new portal file
        {state.read_since_6 > 0 && ` (${state.read_since_6} read since 06:00)`}. Last check {ago(state.last_check_at, nowMs)}.
      </p>
      <p className="mt-1 text-sm text-ink-3">When something needs a decision, it shows up here first.</p>
    </section>
  )
}

function Via({ a }: { a: ActivityItem }) {
  const v = viaOf(a)
  if (!v) return null
  const chip = 'inline-flex max-w-full items-center gap-1 rounded bg-ok/10 px-1.5 py-0.5 text-xs font-semibold text-ok'
  return v.kind === 'routine' ? (
    <span className={chip} title={`Handled by the routine "${v.name}"`}>
      <Workflow size={12} className="shrink-0" /> <span className="truncate">By routine · {v.name}</span>
    </span>
  ) : (
    <span className={chip}><Mic size={12} className="shrink-0" /> By voice</span>
  )
}

function Activity({ items }: { items: ActivityItem[] }) {
  if (!items.length) return null
  return (
    <section className="pt-2">
      <h2 className={HEADING}>Activity</h2>
      <ul className="mt-2 divide-y divide-line">
        {items.slice(0, 12).map((a, i) => (
          <li key={i} className="flex gap-3 py-2.5 text-[15px]">
            <span className="w-[72px] shrink-0 pt-px text-sm tabular-nums text-ink-3">
              {a.at ? `${fmtDay(a.at)} ${fmtTime(a.at)}` : ''}
            </span>
            <span className="min-w-0 text-ink-2">
              <span className="break-words">{sentence(a.text)}</span>
              {a.detail && <span className="block text-sm text-ink-3">{tidy(a.detail)}</span>}
              {viaOf(a) && <span className="mt-1 block"><Via a={a} /></span>}
            </span>
          </li>
        ))}
      </ul>
    </section>
  )
}
import { Check, ChevronRight, FileSearch, MoreHorizontal, Phone, Workflow } from 'lucide-react'
import { useEffect, useRef, useState } from 'react'
import { Button } from '@/components/ui/button'
import { VoiceCall } from '@/components/VoiceCall'
import {
  COLORS, DONE_WORD, costText, fmtDay, fmtNum, fmtTime, partName, post, sentence, tidy, until, type Card,
} from '@/lib/api'
import { cn } from '@/lib/utils'

interface Props {
  card: Card
  nowMs: number
  /** All cards, to give a part code a readable name. */
  cards?: Card[]
  isNew?: boolean
  /** Opened from the deep link (/d/<id>): whoever it is routed to can act on it here. */
  direct?: boolean
  onChanged: () => void
  onHover?: (routes: string[]) => void
  onDrawer: (card: Card, tab: 'evidence' | 'trail') => void
  ringing?: boolean
  onRingingDone?: () => void
}

// A person's first name; a role ('Head of Procurement', 'DC site lead') stays whole.
const first = (s?: string) => (!s ? '' : /\s[a-z]/.test(s) ? s : (s.split(' ').find((w) => !w.endsWith('.')) ?? s))

// Same split as the evidence drawer: what the system says against what a document says.
const SYSTEM = /system|sap|erp|plan|book stock/i
const PAPER = /paper|document|scan|advice|confirmation|delivery note|notice|invoice/i
const sourceName = (src: string | undefined, fallback: string) =>
  (src ?? '').replace(/^(System|Paper) says\s*·?\s*/i, '').trim() || fallback

function mismatch(card: Card) {
  const sys = card.evidence.findIndex((e) => SYSTEM.test(e.source ?? '') && e.value != null)
  const doc = card.evidence.findIndex((e, i) => i !== sys && PAPER.test(e.source ?? '') && e.value != null)
  if (sys < 0 || doc < 0) return null
  const s = card.evidence[sys]
  const d = card.evidence[doc]
  return {
    system: { label: sourceName(s.source, 'System'), value: tidy(String(s.value)) },
    doc: { label: sourceName(d.source, 'Document'), value: tidy(String(d.value)) },
  }
}

export function DecisionCard({
  card, nowMs, cards, isNew, direct, onChanged, onHover, onDrawer, ringing, onRingingDone,
}: Props) {
  const [sel, setSel] = useState(() => Math.max(0, card.options.findIndex((o) => o.recommended)))
  const [mode, setMode] = useState<'idle' | 'edit' | 'escalate'>('idle')
  const [text, setText] = useState('')
  const [note, setNote] = useState('')
  const [busy, setBusy] = useState(false)
  const [more, setMore] = useState(false)
  const moreRef = useRef<HTMLDivElement>(null)
  const color = COLORS[card.level]
  const opt = card.options[sel]
  const due = until(card.deadline, nowMs)
  const other = card.routed_to_other || card.status === 'escalated'
  const closed = card.status !== 'open' && card.status !== 'escalated'
  const who = first(card.approver) || 'the approver'
  const part = partName(card.part, cards ?? [card])
  const diff = mismatch(card)

  useEffect(() => {
    if (!more) return
    const off = (e: MouseEvent) => { if (!moreRef.current?.contains(e.target as Node)) setMore(false) }
    document.addEventListener('mousedown', off)
    return () => document.removeEventListener('mousedown', off)
  }, [more])

  async function act(fn: () => Promise<unknown>) {
    setBusy(true)
    try { await fn() } finally { setBusy(false) }
  }
  const approve = () =>
    act(async () => {
      await post(`/api/cards/${card.id}/approve`, { option: sel, text: mode === 'edit' ? text : undefined })
      setMode('idle')
      onChanged()
    })
  const escalate = () =>
    act(async () => { await post(`/api/cards/${card.id}/escalate`, { note }); setMode('idle'); onChanged() })
  const dismiss = () => act(async () => { setMore(false); await post(`/api/cards/${card.id}/dismiss`); onChanged() })

  return (
    <article
      id={`card-${card.id}`}
      onMouseEnter={() => onHover?.(card.routes)}
      onMouseLeave={() => onHover?.([])}
      className={cn('relative scroll-mt-4 rounded-2xl border border-line bg-white p-4 pl-5 sm:p-5 sm:pl-6', isNew && 'slide-in', other && 'bg-panel')}
    >
      <span className="absolute inset-y-0 left-0 w-1.5 rounded-l-2xl" style={{ background: color }} />

      <div className="flex min-w-0 items-center gap-x-1.5 text-sm text-ink-3">
        <span className="shrink-0 font-semibold text-ink-2">{card.supplier_name || part || 'Soony'}</span>
        {card.supplier_name && part && <span className="truncate" title={part}>· {part}</span>}
      </div>

      <h2 className="mt-1.5 text-[19px] font-bold leading-snug sm:text-[21px]">{tidy(card.headline)}</h2>

      <div className="mt-4 flex flex-wrap items-end gap-x-8 gap-y-3">
        {card.number != null && card.number > 0 && (
          <div>
            <div className="text-[34px] font-extrabold leading-none tabular-nums sm:text-[40px]" style={{ color }}>{fmtNum(card.number)}</div>
            <div className="mt-1 text-sm font-medium text-ink-3">{card.number_label}</div>
          </div>
        )}
        {card.deadline && !closed && (
          <div>
            <div className={cn('text-[24px] font-extrabold leading-none tabular-nums sm:text-[28px]', due?.urgent && 'text-stop')}>
              {fmtDay(card.deadline)} {fmtTime(card.deadline)}
            </div>
            <div className="mt-1 text-sm font-medium text-ink-3">Decide by{due ? ` · ${due.text}` : ''}</div>
          </div>
        )}
      </div>

      {diff && (
        <button
          onClick={() => onDrawer(card, 'evidence')}
          className="group mt-4 block w-full cursor-pointer rounded-lg border border-line px-3 py-2 text-left text-sm hover:bg-panel"
          title="Open the evidence"
        >
          <span className="grid grid-cols-2 gap-3">
            <Says head="System" label={diff.system.label} value={diff.system.value} />
            <Says head="Document" label={diff.doc.label} value={diff.doc.value} strong />
          </span>
          <span className="mt-1.5 inline-flex items-center gap-1 text-xs font-semibold text-ok group-hover:underline">
            They do not match · see the documents <ChevronRight size={13} />
          </span>
        </button>
      )}

      {other && (
        <div className="mt-4 flex items-start gap-2 rounded-lg bg-white px-3 py-2 text-sm text-ink-2 ring-1 ring-line">
          <Phone size={16} className="mt-0.5 shrink-0 text-ink-3" />
          <div>
            <span className="font-semibold text-ink">
              {card.status === 'escalated'
                ? `Waiting for ${who}`
                : `With ${who}${card.called_at ? ` · called ${fmtTime(card.called_at)}` : ''}`}
            </span>
            {card.reason && <div>{sentence(card.reason)}</div>}
          </div>
        </div>
      )}

      {closed && (
        <div className="mt-4 flex items-center gap-2 rounded-lg bg-ok/10 px-3 py-2 text-[15px] font-semibold text-ok">
          <Check size={18} /> {DONE_WORD[card.status] ?? 'Done'}
          {card.ui?.at && <span className="font-normal text-ink-2">· {fmtDay(card.ui.at)} {fmtTime(card.ui.at)}</span>}
        </div>
      )}

      {(!other || direct) && !closed && opt && (
        <>
          <div className="mt-4 rounded-xl border-2 p-4" style={{ borderColor: `${color}55`, background: `${color}0d` }}>
            <div className="text-xs font-bold uppercase tracking-wide" style={{ color }}>
              {opt.recommended || (sel === 0 && !card.options.some((o) => o.recommended)) ? 'We recommend' : 'Your choice'}
            </div>
            <div className="mt-1 text-[17px] font-bold leading-snug">{sentence(opt.action)}</div>
            {opt.effect && <div className="mt-1 text-[15px] text-ink-2">{sentence(opt.effect)}</div>}
            <div className="mt-2 inline-flex rounded-md bg-white/80 px-2 py-0.5 text-sm font-semibold text-ink ring-1 ring-line">
              {costText(opt.cost)}
            </div>
          </div>

          {card.options.length > 1 && (
            <ul className="mt-2 space-y-0.5">
              {card.options.map((o, i) =>
                i === sel ? null : (
                  <li key={i}>
                    <button
                      onClick={() => { setSel(i); setMode('idle') }}
                      className="flex w-full cursor-pointer items-start gap-2 rounded-lg px-3 py-2 text-left text-[15px] text-ink-2 hover:bg-panel"
                    >
                      <ChevronRight size={16} className="mt-0.5 shrink-0 text-ink-3" />
                      <span className="min-w-0 font-medium">
                        <span className="text-ink-3">Or: </span>{sentence(o.action)}
                      </span>
                      <span className="ml-auto shrink-0 pl-2 text-sm text-ink-3">{costText(o.cost)}</span>
                    </button>
                  </li>
                ),
              )}
            </ul>
          )}

          {mode === 'edit' && (
            <textarea
              value={text}
              onChange={(e) => setText(e.target.value)}
              rows={5}
              className="mt-3 w-full rounded-lg border border-line p-3 text-[15px] focus:outline-2 focus:outline-ok"
              aria-label="Edit draft"
            />
          )}
          {mode === 'escalate' && (
            <div className="mt-3 rounded-lg border border-line p-3">
              <div className="text-xs font-semibold uppercase tracking-wide text-ink-3">Brief for {who}</div>
              <p className="mt-1 text-[15px] text-ink-2">{tidy(card.escalation_brief)}</p>
              <input
                value={note}
                onChange={(e) => setNote(e.target.value)}
                placeholder="Add one line (optional)"
                className="mt-3 h-10 w-full rounded-lg border border-line px-3 text-[15px] focus:outline-2 focus:outline-ok"
              />
              <div className="mt-3 flex gap-2">
                <Button size="sm" disabled={busy} onClick={escalate}>Send to {who}</Button>
                <Button size="sm" variant="ghost" onClick={() => setMode('idle')}>Cancel</Button>
              </div>
            </div>
          )}

          <div className="mt-4 flex flex-wrap items-center gap-2">
            <Button disabled={busy} onClick={approve} className="w-full px-6 sm:w-auto">
              <Check size={18} /> {mode === 'edit' ? 'Approve edited' : 'Approve'}
            </Button>
            <Button
              variant="outline"
              disabled={!opt.draft && mode !== 'edit'}
              title={opt.draft ? undefined : 'This option has no draft to edit'}
              onClick={() => { setText(opt.draft ?? ''); setMode(mode === 'edit' ? 'idle' : 'edit') }}
            >
              Edit
            </Button>
            <Button variant="outline" onClick={() => setMode(mode === 'escalate' ? 'idle' : 'escalate')}>Escalate</Button>
            <div ref={moreRef} className="relative ml-auto">
              <Button variant="ghost" className="w-11 px-0" aria-label="More actions" onClick={() => setMore(!more)}>
                <MoreHorizontal size={18} />
              </Button>
              {more && (
                <div className="absolute right-0 top-12 z-20 w-56 rounded-xl border border-line bg-white p-1 shadow-lg">
                  <button
                    disabled={busy}
                    onClick={dismiss}
                    className="w-full cursor-pointer rounded-lg px-3 py-2 text-left text-[15px] font-semibold text-ink-2 hover:bg-panel"
                  >
                    Dismiss
                    <span className="block text-xs font-normal text-ink-3">Nothing to do; take it off the list</span>
                  </button>
                </div>
              )}
            </div>
          </div>
        </>
      )}

      {card.ui?.reply && (
        <div className="mt-4 rounded-xl border-2 border-ok/30 bg-ok/5 p-4">
          <div className="text-xs font-bold uppercase tracking-wide text-ok">
            Reply from {card.ui.reply_from || 'supplier'}
            {card.ui.reply_at ? ` · ${fmtDay(card.ui.reply_at)} ${fmtTime(card.ui.reply_at)}` : ''}
          </div>
          <p className="mt-1 text-[15px] font-medium leading-snug">{card.ui.reply}</p>
          {card.ui.reply_text && (
            <details className="mt-2">
              <summary className="cursor-pointer text-sm text-ink-3">Original email</summary>
              <pre className="mt-1 whitespace-pre-wrap break-words font-sans text-sm text-ink-2">{card.ui.reply_text}</pre>
            </details>
          )}
        </div>
      )}

      {!closed && <VoiceCall card={card} onChanged={onChanged} ringing={ringing} onRingingDone={onRingingDone} />}

      <div className="mt-4 flex gap-5 border-t border-line pt-3 text-sm font-semibold text-ink-2">
        <button className="inline-flex cursor-pointer items-center gap-1.5 hover:text-ink" onClick={() => onDrawer(card, 'evidence')}>
          <FileSearch size={16} /> Evidence
        </button>
        <button className="inline-flex cursor-pointer items-center gap-1.5 hover:text-ink" onClick={() => onDrawer(card, 'trail')}>
          <Workflow size={16} /> Agent trail
        </button>
      </div>
    </article>
  )
}

function Says({ head, label, value, strong }: { head: string; label: string; value: string; strong?: boolean }) {
  return (
    <span className="block min-w-0 leading-snug">
      <span className="block truncate text-xs text-ink-3" title={label}>
        <span className="font-semibold uppercase tracking-wide">{head}</span>
        {label !== head && ` · ${label}`}
      </span>
      <span className={cn('mt-0.5 block font-semibold', strong ? 'text-stop' : 'text-ink')}>{value}</span>
    </span>
  )
}
import { ExternalLink } from 'lucide-react'
import { useEffect, useState } from 'react'
import { type Anchor, AnchorList, CitedText, OpenAnchor, useAnchors } from '@/components/SourceAnchors'
import { Sheet, SheetContent, SheetDescription, SheetTitle } from '@/components/ui/sheet'
import { fmtDay, fmtTime, tidy, type Card } from '@/lib/api'

export type DrawerView = { card: Card; tab: 'evidence' | 'trail' } | null

export function EvidenceDrawer({ view, onClose }: { view: DrawerView; onClose: () => void }) {
  const card = view?.card
  return (
    <Sheet open={!!view} onOpenChange={(o) => !o && onClose()}>
      {card && view && (
        <SheetContent>
          <div className="border-b border-line px-6 pb-4 pt-6 pr-14">
            <div className="text-xs font-semibold uppercase tracking-wide text-ink-3">
              {view.tab === 'evidence' ? 'Evidence' : 'Agent trail'}
            </div>
            <SheetTitle className="mt-1 text-xl font-bold leading-snug">{card.headline}</SheetTitle>
            <SheetDescription className="sr-only">Source documents and agent steps behind this decision</SheetDescription>
          </div>
          <div className="flex-1 space-y-4 overflow-y-auto px-6 py-5">
            {view.tab === 'evidence' ? <Evidence card={card} /> : <Trail card={card} />}
          </div>
        </SheetContent>
      )}
    </Sheet>
  )
}

const SYSTEM = /system|sap|erp|plan|book stock/i
const PAPER = /paper|document|scan|advice|confirmation|delivery note|notice|invoice/i

function Evidence({ card }: { card: Card }) {
  const anchors = useAnchors(card.id)
  if (!card.evidence.length) return <p className="text-ink-2">No source documents attached to this decision yet.</p>
  // Lead with the contradiction: what the system says against what the paper says, each with its
  // source opened at the spot. Everything else follows as supporting evidence.
  const sys = card.evidence.findIndex((e) => SYSTEM.test(e.source ?? ''))
  const paper = card.evidence.findIndex((e, i) => i !== sys && PAPER.test(e.source ?? ''))
  const pair = sys >= 0 && paper >= 0 ? [sys, paper] : []
  const rest = card.evidence.map((e, i) => [e, i] as const).filter(([, i]) => !pair.includes(i))
  const order = [...pair, ...rest.map(([, i]) => i)]
  const all = order.flatMap((i) => anchors.items?.[i] ?? [])
  const [open, setOpen] = useState<Anchor | null>(null)
  const point = card.summary || card.reason
  return (
    <>
      {point && (
        <div>
          <p className="text-[17px] leading-relaxed text-ink">
            <CitedText text={point} anchors={all} active={open} onOpen={setOpen} />
          </p>
          <OpenAnchor anchor={open} />
        </div>
      )}
      {pair.length > 0 && (
        <div className="space-y-2">
          <Side e={card.evidence[sys]} tone="system" anchors={anchors.items?.[sys]} ready={anchors.ready} />
          <div className="flex items-center gap-2 px-1 text-sm font-bold text-stop">
            <span className="h-px flex-1 bg-stop/30" /> does not match <span className="h-px flex-1 bg-stop/30" />
          </div>
          <Side e={card.evidence[paper]} tone="paper" anchors={anchors.items?.[paper]} ready={anchors.ready} />
        </div>
      )}
      {rest.length > 0 && (
        <>
          {pair.length > 0 && <div className="pt-2 text-xs font-semibold uppercase tracking-wide text-ink-3">More evidence</div>}
          {rest.map(([e, i]) => (
            <section key={i} className="rounded-xl border border-line p-4">
              <div className="flex items-baseline justify-between gap-3">
                <div className="text-[15px] font-semibold">{e.source && !/^evidence$/i.test(e.source) ? e.source : 'Supporting note'}</div>
                {e.value != null && String(e.value).length <= 24 && <div className="text-xl font-extrabold tabular-nums">{typeof e.value === 'number' ? e.value.toLocaleString('en-GB') : e.value}</div>}
              </div>
              {e.value != null && String(e.value).length > 24 && <p className="mt-1.5 text-[15px] font-semibold text-ink">{e.value}</p>}
              {e.quote && (
                <blockquote className="mt-3 border-l-4 border-line pl-3 text-[15px] text-ink">
                  “{e.quote}”
                  {e.language && <span className="ml-2 text-xs uppercase text-ink-3">{e.language}</span>}
                </blockquote>
              )}
              {e.translation && <p className="mt-2 text-sm text-ink-2">In English: {e.translation}</p>}
              {e.doc && !anchors.items?.[i]?.length && (
                <a
                  href={`/api/file?path=${encodeURIComponent(e.doc)}${e.page ? `#page=${e.page}` : ''}`}
                  target="_blank"
                  rel="noreferrer"
                  className="mt-3 inline-flex items-center gap-1.5 text-sm font-semibold text-ok hover:underline"
                >
                  Open source document{e.page ? `, page ${e.page}` : ''} <ExternalLink size={14} />
                </a>
              )}
              <AnchorList anchors={anchors.items?.[i]} ready={anchors.ready} />
            </section>
          ))}
        </>
      )}
    </>
  )
}

function Side({ e, tone, anchors, ready }: {
  e: Card['evidence'][number]; tone: 'system' | 'paper'; anchors?: Anchor[]; ready: boolean
}) {
  const [open, setOpen] = useState<Anchor | null>(null)
  const list = anchors ?? []
  const first = list[0]
  useEffect(() => {
    if (tone === 'paper' && first) setOpen((o) => o ?? first) // show the document right away
  }, [tone, first])
  const cited = (t: string) => <CitedText text={t} anchors={list} active={open} onOpen={setOpen} />
  return (
    <section className={tone === 'system' ? 'rounded-xl border border-line bg-panel p-4' : 'rounded-xl border-2 border-stop/40 bg-white p-4'}>
      <div className="text-xs font-bold uppercase tracking-wide text-ink-3">{tone === 'system' ? 'The system says' : 'The document says'}</div>
      <div className="mt-1 text-[22px] font-extrabold leading-tight tabular-nums">{tidy(String(e.value ?? ''))}</div>
      <div className="mt-1 text-sm text-ink-2">{e.source?.replace(/^(System|Paper) says\s*·\s*/i, '')}</div>
      {e.quote && <blockquote className="mt-2 border-l-4 border-line pl-3 text-sm leading-relaxed text-ink">“{cited(String(e.quote))}”</blockquote>}
      {e.translation && <p className="mt-1.5 text-sm text-ink-2">In English: {e.translation}</p>}
      <OpenAnchor anchor={open} />
      {list.length === 0 && <AnchorList anchors={anchors} ready={ready} />}
    </section>
  )
}

function Trail({ card }: { card: Card }) {
  if (!card.trail.length) return <p className="text-ink-2">No agent steps recorded for this decision yet.</p>
  return (
    <ol className="space-y-4">
      {card.trail.map((t, i) => (
        <li key={i} className="relative border-l-2 border-line pl-4">
          <span className="absolute -left-[5px] top-1.5 h-2 w-2 rounded-full bg-ok" />
          <div className="text-sm font-semibold">
            {t.agent}
            {t.at && <span className="ml-2 font-normal text-ink-3">{fmtDay(t.at)} {fmtTime(t.at)}</span>}
          </div>
          <div className="text-[15px] text-ink-2">{t.text}</div>
        </li>
      ))}
    </ol>
  )
}
